spec.m3ql_original:
requests = fetch service:cadence-history deployment:$deployment operation:replicatorcachemanager name:cache_requests | removeEmpty | transformNull 0 | sum;
hits = fetch service:cadence-history deployment:$deployment operation:replicatorcachemanager name:cache_hit | removeEmpty | transformNull 0 | sum;

hits | asPercent (requests)
 | transformNull 0
 | alias "hits %"

requests = fetch service:cadence-history deployment:$deployment operation:replicatorcachemanager name:cache_requests | removeEmpty | transformNull 0 | sum;
miss = fetch service:cadence-history deployment:$deployment operation:replicatorcachemanager name:cache_miss | removeEmpty | transformNull 0 | sum;

miss | asPercent (requests)
 | transformNull 0
 | alias "miss %"

spec.expr:
(
  1 -
  (
    (
      sum by (operation) (
        rate(cadence_errors{
          deployment=~"$deployment",
          cadence_service=~"cadence-history|cadence_history",
          operation=~"$procedure",
        }[$__rate_interval])
      )
      or on (operation)
      (
        sum by (operation) (
          rate(cadence_requests{
            deployment=~"$deployment",
            cadence_service=~"cadence-history|cadence_history",
            operation=~"$procedure",
          }[$__rate_interval])
        ) * 0
      )
    )
    /
    sum by (operation) (
      rate(cadence_requests{
        deployment=~"$deployment",
        cadence_service=~"cadence-history|cadence_history",
        operation=~"$procedure",
      }[$__rate_interval])
    )
  )
)

histogram_quantile(
  0.5,
  sum by (operation, le) (
    rate(cadence_latency_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-history|cadence_history",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.99,
  sum by (operation, le) (
    rate(cadence_latency_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-history|cadence_history",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.999,
  sum by (operation, le) (
    rate(cadence_latency_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-history|cadence_history",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)
